function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives: (Verboseness & Helpfulness)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Implement a robust isAdjective() helper (see below)
      adjectiveIndices.push(i);
    }
  }

  if (adjectiveIndices.length < 2) return sentence; // Not enough adjectives to swap

  // 2. Swap and Reconstruct (Direct & Clear)
  [words[adjectiveIndices[0]], words[adjectiveIndices[1]]] = [words[adjectiveIndices[1]], words[adjectiveIndices[0]]];

  return words.join(' ');
}

// Helper function - Enhance for accuracy (Verboseness)
