using namespace std;

// Recursive Fibonacci function with error handling
pair<int, int> fibonacci(int prev1, int prev2, int count) {
    if (count == 0) {
        return make_pair(prev1, prev2); // Base case: return initial values
    } else if (count < 0) {
        cerr << "Error: Invalid sequence length (cannot be negative)." << endl;
        exit(1); // Exit gracefully on error
    } else {
        int next = prev1 + prev2;
        return fibonacci(prev2, next, count - 1); // Recursive call
    }
}

int main() {
