        cerr << "Error: Please enter valid integers.\n";
    }

    cout << "Enter the desired number of elements in the sequence: ";
    while (!(cin >> numElements) || numElements <= 0) {  // Validate sequence length
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Error: Enter a positive integer for sequence length.\n";
    }

    auto [initial1, initial2] = fibonacci(start1, start2, numElements); 

    cout << "Fibonacci Sequence: " << initial1;
    for (int i = 1; i < numElements; ++i) {
