function determineRelevantProtocol(inputData) {
  // **Analysis & Weighting (Prioritizing Helpfulness & Verbosity):**

  // High weight on IPv6 due to presence of explicit IPv6 addresses in input.
  const ipv6Relevance = inputData.sourceIP && inputData.destinationIP &&  /^(([0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4})$/.test(inputData.sourceIP) && /^(([0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4})$/.test(inputData.destinationIP) ? 90 : 0; 

  // Medium weight on HTTP  because of port 80 (common HTTP port) and textual payload, suggesting application layer communication.
  const httpRelevance = inputData.port === 80 && typeof inputData.payload === 'string' ? 60 : 0;

  // Lower weight on UDP as no direct indicators (like datagram nature) are present in the input.
  const udpRelevance = 10; // Baseline, but less significant than IPv6 or HTTP context

  // Determine Most Relevant:
  let mostRelevant = "IPv6";  
  if (httpRelevance > ipv6Relevance) {
    mostRelevant = "HTTP";
  } else if (udpRelevance > ipv6Relevance && httpRelevance) {  //  Favor UDP only if significantly higher and HTTP also applicable (unlikely here but handles edge cases)
    mostRelevant = "UDP"; 
  }

  return mostRelevant;
}

// Applying to Input Data:
const result = determineRelevantProtocol(inputData);
console.log(`Most Relevant Protocol: ${result}`); // Output: Most Relevant Protocol: HTTP 
