import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { User } from '@prisma/client';

@Injectable()
export class RolesGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector, private prisma: PrismaService) { super(); }

  async canActivate(context: any): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    const user = context.user as User;

    if (!requiredRoles || !user) return false;

    const userRoles = await this.prisma.userRole.findMany({ where: { userId: user.id } });
    const validRoles = userRoles.map(role => role.roleId).filter(roleId => requiredRoles.includes(roleId));

    return validRoles.length > 0;
  }
}

// Example Permission Array (within AppModule or a central config)
export const PERMISSIONS = [
  'READ_DATA', 'CREATE_USER', 'MANAGE_ROLES', 'ADMIN', // ...more permissions
];
```

**Explanation (for clarity, NOT part of the merged `index.js`):**

1. **`RolesGuard`:** A custom Auth Guard leveraging JWT authentication (`@nestjs/passport`). It extracts `roles` metadata from decorated routes using `@Roles('role1', 'role2')` (metadata decorator to be defined separately).
2. **Permission Fetching & Comparison:**  Dynamically retrieves a user's assigned roles from the database (using Prisma) and compares them against the required roles for the accessed route.
3. **`PERMISSIONS` Array:**  A centralized list of predefined permission names, serving as a standard reference. This array *should* be populated and managed in your application's configuration or a dedicated service for robust permission management.
4. **Integration:**  Within your NestJS controllers/routes, apply `@UseGuards(RolesGuard)` along with `@Roles(...)` decorators to enforce access control based on roles and the defined permissions.


