<?php

function smart_sort_array(array $set, string $order = 'asc'): array {
    /**
     * Sorts an array of associative sub-arrays (with 'name', 'address', 'age' keys) based on 'age', respecting the provided order.
     *
     * @param array $set  The input array of sub-arrays.
     * @param string $order 'asc' (ascending) or 'desc' (descending). Defaults to 'asc'.
     * @return array The sorted array.
     */
    usort($set, function($a, $b) use ($order) {
        $comparison = $order === 'asc' ? 1 : -1; // Determine comparison direction
        return $comparison * ($a['age'] - $b['age']); 
    });
    return $set;
}

// Example Usage:
$data = [
    ['name' => 'Alice', 'address' => '123 Main', 'age' => 25],
    ['name' => 'Bob', 'address' => '456 Oak', 'age' => 30],
    ['name' => 'Charlie', 'address' => '789 Pine', 'age' => 20]
];

$sortedAscending = smart_sort_array($data); // Sorted by age in ascending order
$sortedDescending = smart_sort_array($data, 'desc'); // Sorted by age in descending order

var_dump($sortedAscending);
var_dump($sortedDescending);
```

